ROCK = P("a natural stone arch spanning a gap; a tall stone pillar balanced on a thin base; a row of hexagonal basalt columns; a flat-topped mesa with banded layers; a rounded boulder perched on a smooth slab; a sea stack standing offshore; a field of tall thin hoodoos; a wall of folded rock layers; a huge granite dome; a narrow slot canyon with smooth curved walls; a cave mouth ringed with dripping stone; a ridge of jagged limestone teeth; a split boulder with a bright gap; a smooth sandstone wave frozen in stone")
WATER = P("a tall waterfall dropping into a pool; a series of stepped cascades; fast white rapids between boulders; a quiet oxbow lake in a curve of river; a steaming hot spring; a clear spring welling from the ground; a wide slow river; a mountain tarn; a still lagoon behind a bar of sand; a babbling brook over pebbles; a tidal inlet at low tide; a frozen stream with ice-covered stones; a flooded meadow reflecting the sky; a small pond with lilies")
def build(final=FINAL):
    G = {'land_season': SEASON, 'land_time': TIME, 'land_sky': SKY, 'land_clouds': CLOUDS, 'land_night_sky': NIGHT, 'land_rock_formation': ROCK, 'land_water_feature': WATER}
    for b, txt in FLORA.items():
        items = [x.strip().capitalize() if False else x.strip() for x in txt.split(';')]
        G['flora_%s' % b] = [i[:1].upper() + i[1:] for i in items]
    G['flora_biomes'] = sorted(FLORA)
    G['flora_prompt'] = ['A group of __flora_%s__, __land_season__.' % b for b in FLORA]
    pro = []
    for t, spec in L.items():
        biome, feat, veg, wat, fore, scale = spec.split('|'); s = slug(t)
        for k, v in dict(feature=feat, vegetation=veg, water=wat, foreground=fore, scale=scale).items(): G['land_%s_%s' % (s, k)] = P(v)
        tail = ' The scene is __land_season__, __land_time__, under __land_sky__.' if t != 'cave' else ' The only light is a soft glow from a single lamp and a distant opening.'
        G['land_%s_prompt' % s] = ['%s, with __land_%s_feature__. Vegetation is __land_%s_vegetation__. Water is __land_%s_water__. In the foreground, __land_%s_foreground__. For scale, __land_%s_scale__.%s' % (an(t), s, s, s, s, s, tail)]
        pro.append('__land_%s_prompt__' % s)
    G['land_names'] = sorted(L); G['land_prompt'] = pro
    G['land_close_prompt'] = ['__land_rock_formation__, __land_time__, under __land_sky__.', '__land_water_feature__, __land_season__, __land_time__.']
    G['land_night_prompt'] = ['A wide dark landscape under __land_night_sky__, with the shapes of __land_rock_formation__ against the sky.']
    G['land_frame_prompt'] = ['__frame_clarity__ __frame_ratio__ __land_prompt__ __frame_landscape__']
    G['v60_entry_points'] = ['land_prompt', 'land_close_prompt', 'land_night_prompt', 'land_frame_prompt', 'flora_prompt', 'land_names', 'flora_biomes']
    return G
def run(final): return run_mod(sys.modules[__name__], final)
def export_aoo(out): return export_aoo_mod(build(FINAL), out)
if __name__ == '__main__': run(FINAL)
